using System;
public abstract class BaseClass<T>
{
    public abstract int Method(T input);
}

public class DerivingClass<T> : BaseClass<T>
{
    [Obsolete("Deprecated")]
    public override void Method(T input)
    {
        throw new NotImplementedException();
    }
}

